  /*
   * One flat, alphabetically sorted map, and the union of two branches
   * that both translated into Portuguese.
   *
   * Where they disagree, the owner wins: `landing.*` and `blog.*` come
   * from this branch, which is where the public copy is written and where
   * four stale strings were fixed; everything else comes from main, whose
   * workstream maintains the application's Portuguese.
   *
   * Resolving this the other way round — main wins everywhere — silently
   * reverted those four fixes, and the parity gate caught it. That is what
   * the gate is for.
   *
   * ── Merged with main a second time, after #135 landed ──
   *
   * The sort makes this file conflict wholesale with any branch that inserts
   * into the old ordering, and #135 did: 78 keys (55 `conn.*`, 16
   * `proRibbon.*`, 7 `profileSelector.*`) for the metallic surface. A
   * three-way comparison against the common ancestor found ZERO keys touched
   * by both sides, so there was nothing to arbitrate — the resolution is the
   * union, and the one key whose value differs (`landing.blogBody`) is this
   * branch's deliberate rewrite to stop the section describing one post.
   *
   * If this conflicts again, that is the shape to expect. What must NOT
   * happen is taking either file wholesale: this branch's version alone
   * drops the 78 Portuguese strings of the metallic UI into the silent
   * English fallback, and nothing in CI would say so — `locale-parity` is
   * scoped to `design.*`, and the landing gate only reads `landing.*`
   * and `blog.*`.
   */
