  'advHelp.cirsocFlex.label': 'Calculadora de concreto armado',
  'advHelp.cirsocFlex.text': 'Dimensiona ou verifica uma seção de concreto armado por si só, sem modelo resolvido: você informa a geometria, os materiais e a solicitação. Cinco casos, os mesmos que a planilha CIRSOC FLEX imprime — retangular e com mesa em flexão simples, pilares retangular e circular com axial mais flexão, e pilar retangular em flexão oblíqua. Dimensionar devolve a armadura necessária; verificar devolve o aproveitamento da armadura informada.',
  'advHelp.buckling.label': 'Pcr — Carga crítica (Euler)',
  'advHelp.buckling.text': 'Calcula a carga de flambagem elástica via autovalores da matriz de rigidez geométrica. O fator λ_cr indica quanto as cargas atuais precisariam ser multiplicadas para a estrutura flambar. Se λ_cr < 1, a estrutura já excedeu sua carga crítica. Mostra o comprimento efetivo (Keff) de cada barra comprimida.',
  'advHelp.dsm.label': 'Passo a Passo — Método da Rigidez Direta',
  'advHelp.dsm.text': 'Mostra cada passo do Método da Rigidez Direta em detalhe: numeração de GDL, matrizes de rigidez locais [k], transformações [T], montagem global [K], vetor de cargas {F}, condições de contorno, solução do sistema {u} = [K]⁻¹{F}, e extração de reações e esforços internos. Ideal para estudar e aprender o método.',
  'advHelp.envelope.label': 'Envoltória de Esforços',
  'advHelp.envelope.text': 'Envoltória de esforços das combinações de carga. Resolve cada caso de carga separadamente e combina com os fatores definidos na tabela de combinações (ex: 1.2D + 1.6L). Mostra a envoltória máxima e mínima (+/−) de momento, cortante e normal. Permite comparar combinações individuais no dropdown "Primário" em Configurações → Resultados. Requer combinações definidas na aba "Combinações".',
  'advHelp.influenceLine.label': 'Linha de influência',
  'advHelp.influenceLine.text': 'Mostra como uma grandeza fixa (reação, momento ou cortante em uma seção específica) varia quando uma carga unitária P=1 percorre a estrutura. Clique em um nó para ver a LI de suas reações (Rz, Rx, My) ou em uma barra para M ou V naquela seção. Ferramenta clássica para projeto de pontes e cargas móveis.',
  'advHelp.kinematic.label': 'Análise cinemática',
  'advHelp.kinematic.text': 'Análise passo a passo da estabilidade cinemática da estrutura. Mostra o grau de hiperestaticidade (fórmula detalhada com cada apoio e articulação), verifica numericamente pelo posto de Kff se existem mecanismos ocultos, e sugere correções se a estrutura é instável. Funciona sem resolver: é calculada ao abrir e, com Cálculo em tempo real ativado, é atualizada ao modificar o modelo.',
  'advHelp.modal.label': 'Análise dinâmica (modal)',
  'advHelp.modal.text': 'Calcula modos de vibração e frequências naturais usando a matriz de massa consistente. Reporta: frequência (Hz), período (s), massa modal efetiva (%) em X e Y, e coeficientes de amortecimento de Rayleigh. Pré-requisito para análise espectral. Requer densidade do material (ρ).',
  'advHelp.pdelta.label': 'P-Δ (2ª ordem)',
  'advHelp.pdelta.text': 'Análise geometricamente não linear. Considera como as forças axiais modificam a rigidez lateral da estrutura (efeito P-Δ). Itera até convergência e reporta o fator de amplificação B₂. Se B₂ > 1,4, a estrutura é sensível a efeitos de segunda ordem. Resolve o modelo por conta própria: não é preciso calcular antes.',
  'advHelp.plastic.label': 'Colapso plástico',
  'advHelp.plastic.text': 'Análise incremental que forma rótulas plásticas nos pontos onde o momento atinge Mp (momento plástico = Wpl × fy). A cada passo, a estrutura é recalculada com a nova rótula. O fator λ indica quanto multiplicar as cargas para atingir o mecanismo de colapso. Requer fy do material.',
  'advHelp.spectral.label': 'Análise espectral (CIRSOC 103)',
  'advHelp.spectral.text': 'Combinação modal espectral com espectro de projeto sísmico CIRSOC 103 (Argentina). Calcula o cortante basal, deslocamentos e esforços máximos combinando os modos por CQC ou SRSS. Requer análise dinâmica prévia. Usa Zona 4, Solo tipo II por padrão.',
  'advHelp.stress.label': 'Tensões — Análise de seção',
  'advHelp.stress.text': 'Análise completa de tensões em seções transversais. Clique em uma barra para ver: tensão normal σ (Navier: σ = N/A + M·y/I), tensão de cisalhamento τ (Jourawski: τ = V·Q/(I·b)), tensão equivalente de Von Mises (σ_vm = √(σ² + 3τ²)), círculo de Mohr com tensões principais, diagrama de fluxo de cisalhamento para perfis de parede fina, e aproveitamento em relação a fy. Inclui um controle deslizante para percorrer fibras da seção (0=inferior, 1=superior) e navegação para seções críticas (momento máximo, apoios, pontos de carga). Suporta seções retangulares, I, U, L, caixão (RHS) e tubulares (CHS).',
  'advHelp.trainLoad.label': 'Trem de carga',
  'advHelp.trainLoad.text': 'Um trem de carga (ex: caminhão HL-93, tandem) percorre a estrutura em múltiplas posições. Em cada posição, a estrutura completa é resolvida e os esforços são registrados. As cargas do trem são ADICIONADAS às cargas existentes do modelo — para ver apenas o efeito do trem, remova outras cargas. Após resolver, use as setas ◀▶ para percorrer posições e "Ver envoltória" para ver os esforços máximos e mínimos. Ferramenta clássica para projeto de pontes e cargas veiculares.',
  'advHelp.whatif.label': 'Explorar (E se…?)',
  'advHelp.whatif.text': 'Painel interativo de análise paramétrica de sensibilidade. Ajuste magnitudes de carga, módulo de elasticidade E do material e propriedades da seção (área A e inércia Iz) em tempo real usando controles deslizantes. A estrutura recalcula instantaneamente a cada mudança (~60ms) mostrando como diagramas, deformadas e reações variam. Ideal para entender o comportamento estrutural, otimizar seções e responder perguntas como "e se eu dobrar a carga?" ou "e se eu usar um perfil mais rígido?". Mudanças são temporárias — o modelo original é restaurado quando o painel é fechado.',
