  'fm.iso.s2': "Com GH = 0 não há nada a liberar: a estrutura fundamental é a própria estrutura.",
  'fm.iso.s3': "O estado 0 já é a resposta: a estrutura é isostática, então as cargas reais dão diretamente os diagramas finais.",
  'fm.iso.none': "Neste passo não há nada a fazer: sem incógnitas não há estados unitários, nem coeficientes de flexibilidade, nem equações de compatibilidade. A estática sozinha deu a resposta no estado 0.",
  'fm.iso.s8': "M = M₀: sem incógnitas não há nada a superpor.",
  'fm.s2.explanation': "Escolhem-se GH forças — as <strong>incógnitas hiperestáticas</strong> X₁…Xₙ — e retiram-se. O que resta é a <strong>estrutura fundamental</strong>: isostática e estável. As Xᵢ passam a ser cargas desconhecidas aplicadas sobre ela.",
  'fm.s2.original': "Estrutura real",
  'fm.s2.primary': "Estrutura fundamental, com as incógnitas como cargas",
  'fm.s2.list': "Incógnitas escolhidas",
  'fm.s2.why': "Critério: primeiro os momentos de engastamento, depois as reações dos apoios intermediários, depois barras de treliça e, se for preciso abrir um anel fechado, um corte numa barra. Verificou-se que a fundamental resultante é estável.",
  'fm.s2.prescribed': "Este apoio tem um deslocamento imposto Δ = {d} m: vai para o segundo membro da sua equação de compatibilidade.",
  'fm.x.reaction0': "Reação horizontal no nó {node}",
  'fm.x.reaction1': "Reação vertical no nó {node}",
  'fm.x.reaction1n': "Reação normal ao plano de rolamento no nó {node}",
  'fm.x.reaction2': "Momento de engastamento no nó {node}",
  'fm.x.barForce': "Esforço normal na barra {el} (retira-se a barra)",
  'fm.x.cutN': "Esforço normal na barra {el}, extremidade {end} (corte)",
  'fm.x.cutV': "Esforço cortante na barra {el}, extremidade {end} (corte)",
  'fm.x.cutM': "Momento fletor na barra {el}, extremidade {end} (corte)",
  'fm.x3.reaction0': "Reação segundo x no nó {node}",
  'fm.x3.reaction1': "Reação segundo y no nó {node}",
  'fm.x3.reaction2': "Reação vertical (z) no nó {node}",
  'fm.x3.reaction3': "Momento segundo x no nó {node}",
  'fm.x3.reaction4': "Momento segundo y no nó {node}",
  'fm.x3.reaction5': "Momento segundo z no nó {node}",
  'fm.x3.normal': "Reação normal ao apoio inclinado no nó {node}",
  'fm.x.cutVy': "Cortante Vy na barra {el}, extremidade {end} (corte)",
  'fm.x.cutVz': "Cortante Vz na barra {el}, extremidade {end} (corte)",
  'fm.x.cutT': 'Momento torsor na barra {el}, extremidade {end} (corte)',
  'fm.x.cutMy': "Momento My na barra {el}, extremidade {end} (corte)",
  'fm.x.cutMz': "Momento Mz na barra {el}, extremidade {end} (corte)",
  'fm.banner3d': "3D · pórticos e treliças espaciais · barras de Euler–Bernoulli, torção de Saint-Venant",
  'fm.s1.barsNote3d': "Cada barra de pórtico espacial traz 6 (N, Vy, Vz, T, My, Mz); cada momento fletor liberado numa extremidade tira um, e uma liberação de torção tira o torçor uma só vez; cada barra de treliça traz 1 (N).",
  'fm.s1.equationsNote3d': "6 por nó (três forças e três momentos), menos as rotações que nenhuma barra resiste: nessas direções não há momento a equilibrar.",
  'fm.s5.explanation3d': "δᵢⱼ é o deslocamento na direção de Xᵢ causado por Xⱼ = 1. No espaço cada barra trabalha a axial, flexão nos dois planos e torção:",
  'fm.src.torsion': "Torção ∫t·t/GJ",
  'fm.diagram.pick': "Diagrama:",
  'fm.s3.explanation': "Resolve-se a fundamental — isostática — com as cargas reais e obtêm-se o diagrama M₀ e os esforços N₀. Ela se deforma livremente justo onde a estrutura real está presa pelas Xᵢ.",
  'fm.s4.explanation': "Resolve-se a fundamental sem cargas e com uma única incógnita valendo 1: Xᵢ = 1. Cada estado dá um diagrama mᵢ. Por linearidade, o estado real será M₀ + Σ Xᵢ·mᵢ.",
  'fm.s3.reactions': "Reações",
  'fm.s3.endMoments': "Momentos nas extremidades das barras",
  'fm.s3.bar': "Barra",
  'fm.s3.node': "Nó",
  'fm.s3.drawn': "Diagrama de momentos desenhado do lado tracionado.",
  'fm.s5.explanation': "δᵢⱼ é o deslocamento na direção de Xᵢ causado por Xⱼ = 1. Pelo princípio dos trabalhos virtuais (Mohr):",
  'fm.s5.symmetry': "A matriz é simétrica: δᵢⱼ = δⱼᵢ (Maxwell–Betti).",
  'fm.s5.pick': "Escolha um coeficiente para ver de onde vem:",
  'fm.s5.breakdown': "Contribuição de cada barra",
  'fm.s5.check': "Verificação: lido como deslocamento da fundamental resolvida por rigidez, o mesmo coeficiente vale {v}.",
  'fm.mx.explanation': "Todo o método numa tela: a matriz de flexibilidade [δ], os termos de carga e a solução. Toque um coeficiente para ver os dois diagramas unitários cujo produto o forma.",
  'fm.mx.clickCell': "toque um coeficiente",
  'fm.mx.hinges': "Rótulas: numa rótula o momento é zero, então todos os mᵢ se anulam ali e as barras ao redor contribuem menos para [δ]. Cada rótula também baixa o GH em um: uma incógnita a menos, uma linha e uma coluna a menos em [δ].",
  'fm.mx.truss': "As barras de treliça só têm esforço normal: sua contribuição para cada coeficiente é nᵢ·nⱼ·L/EA, constante na barra, sem termo de flexão.",
  'fm.mx.barRedundant': "Uma barra retirada é uma incógnita: seu próprio alongamento sob Xᵢ = 1, L/EA, entra em δᵢᵢ; a separação que ela deixa tem que se fechar com a deformação da própria barra.",
  'fm.mx.agrees': "A mesma estrutura pelo método da rigidez dá as mesmas reações e esforços.",
  'fm.s6.explanation': "δᵢ₀ é o deslocamento na direção de Xᵢ no estado 0 — a fundamental com as cargas reais:",
  'fm.s6.extras': "A temperatura soma ∫ nᵢ·α·ΔT dx + ∫ mᵢ·α·Δt/h dx; um apoio que recalca e fica na fundamental soma −Σ Rₖ⁽ⁱ⁾·Δₖ.",
  'fm.src.bending': "Flexão ∫m·m/EI",
  'fm.src.axial': "Axial ∫n·n/EA",
  'fm.src.thermal': "Temperatura",
  'fm.src.spring': "Molas",
  'fm.src.bar': "A própria barra retirada, L/EA",
  'fm.src.settlement': "Recalques",
  'fm.total': "Total",
  'fm.s7.explanation': "Na estrutura real, o deslocamento na direção de cada Xᵢ é o que seu vínculo impõe, quase sempre zero. Superpondo os estados: Σⱼ δᵢⱼ·Xⱼ + δᵢ₀ = Δᵢ. São GH equações com GH incógnitas.",
  'fm.s7.system': "O sistema",
  'fm.s7.solution': "Solução",
  'fm.s7.units': "Forças em kN, momentos em kN·m.",
  'fm.s8.explanation': "Com as Xᵢ conhecidas, tudo sai por superposição: M = M₀ + Σ Xᵢ·mᵢ, e o mesmo para N, V e as reações.",
  'fm.s9.explanation': "A mesma estrutura resolvida pelo método da rigidez tem que dar o mesmo. Dois métodos, uma estrutura:",
  'fm.s9.ok': "Coincidem: a maior diferença é {d}, {pct} da maior força.",
  'fm.s9.bad': "Não coincidem: a maior diferença é {d}.",
  'fm.s9.flex': "Flexibilidade",
  'fm.s9.stiff': "Rigidez",
  'fm.err.hypostatic': "A estrutura é um mecanismo (GH < 0): não pode ser resolvida.",
  'fm.err.noRedundants': "Nenhuma escolha de incógnitas deixa uma fundamental estável: provavelmente a estrutura é em parte um mecanismo.",
  'fm.err.unstable': "A estrutura não é estável.",
  'fm.err.only2d': "O passo a passo pela flexibilidade está disponível em 2D.",
