  'config.tip.drawPositiveTowardLocalAxes': 'De que lado um valor positivo é desenhado: para os eixos locais da barra, ou do lado estrutural — a flexão positiva para baixo, como se desenha à mão.',
  'config.tip.elementIds': 'Escreve o número de cada barra sobre ela, para localizar no modelo um resultado da tabela.',
  'config.tip.gridExtent': 'Até onde a grade chega a partir da origem. É apenas o que você vê: não limita onde pode desenhar.',
  'config.tip.gridSize': 'Distância entre linhas da grade e, portanto, o passo ao qual um nó se ajusta.',
  'config.tip.hideLoadsWithDiagram': 'Esconde as setas de carga enquanto há um diagrama na tela, para que não se sobreponham nas mesmas barras.',
  'config.tip.lengths': 'Rotula cada barra com seu comprimento. Um jeito rápido de detectar um nó colocado um metro fora.',
  'config.tip.localAxes': 'Mostra os eixos próprios de cada barra: as direções em que os esforços internos são medidos. Serve para ler para onde um momento flexiona.',
  'config.tip.localAxesShells': 'O mesmo para placas e quadriláteros: as direções em que seus resultados de flexão e membrana são informados.',
  'config.tip.momentStyle': 'Como um momento é desenhado: uma seta de ponta dupla sobre o eixo em torno do qual gira, ou uma seta curva mostrando o giro.',
  'config.tip.nodeIds': 'Escreve o número de cada nó ao lado — os mesmos números que a tabela de resultados usa.',
  'config.tip.renderMode': 'Barras como linhas, como barras sólidas, ou com sua seção real extrudada ao longo delas. Linhas são o mais rápido num modelo grande.',
  'config.tip.showAxes': 'Desenha os eixos globais X, Y e Z na origem, para saber como o modelo está orientado.',
  'config.tip.showConstraintForces': 'Desenha as forças assumidas pelos deslocamentos impostos e vínculos rígidos: as que não são reações num apoio.',
  'config.tip.showGrid': 'A grade de referência atrás do modelo. Desligá-la não muda como o desenho se ajusta.',
  'config.tip.showLoads': 'Desenha as cargas sobre o modelo. Desligá-las deixa a estrutura nua, mais fácil de ler enquanto você edita a geometria.',
  'config.tip.showPrimarySelector': 'O seletor que escolhe QUAL resultado é exibido: cargas simples, um estado de carga, uma combinação ou a envoltória.',
  'config.tip.showReactions': 'Desenha as forças que os apoios devolvem à estrutura. Sua soma tem de equilibrar a carga aplicada, então são a primeira coisa a conferir.',
  'config.tip.showSecondarySelector': 'O seletor «Comparar», que sobrepõe um segundo resultado ao primeiro para lê-los um contra o outro. Precisa do seletor principal ligado.',
  'config.tip.showValues': 'Escreve os números sobre o diagrama: os picos e as extremidades, em vez de apenas a forma.',
  'config.tip.smoothOrbit': 'A câmera mantém alguma inércia ao soltar o mouse, em vez de parar de repente.',
  'config.tip.snapGrid': 'Os novos nós caem na interseção de grade mais próxima em vez de exatamente onde você clicou.',
  'config.tip.memberDims': 'Enquanto você estica uma barra em 2D, uma etiqueta mostra ΔX, ΔZ e o comprimento. É o mesmo interruptor do botão Cotas da ferramenta Barra.',
  'config.tip.units': 'As unidades em que resultados e detalhes são mostrados: diagramas, tabela de resultados, escala de cores, barra de status e detalhes do nó e da barra. Tabelas de dados, ferramentas, rótulos de carga e grade trabalham sempre em SI (m, kN, MPa).',
