  'diag.tooltip.MODAL_LOW_MASS_PARTICIPATION': 'Não há modos suficientes para capturar a resposta dinâmica com precisão',
  'diag.tooltip.MODEL_COINCIDENT_NODES': 'Dois nós na mesma posição — fundir ou separar',
  'diag.tooltip.MODEL_DISCONNECTED_NODE': 'Nó isolado sem conexão a nenhuma barra — remover ou conectar',
