  'dsm.step2.explanation': 'Para cada barra, a <strong>matriz de rigidez local</strong> [k] é calculada em seu próprio sistema de coordenadas.',
  'dsm.step2.whyTruss': "Barra de treliça: só esforço axial. Em eixos locais aparece apenas EA/L nos GDL axiais; as linhas do deslocamento transversal são nulas e não há rotações: a barra não dá nenhuma rigidez à rotação dos nós.",
  'dsm.step2.whyHinge': "Rótula na extremidade {end}: essa extremidade não transmite momento, então sua rotação θ{end} é condensada e desaparecem sua linha e sua coluna. A barra passa a trabalhar como engastada–rotulada: 12EI/L³ vira 3EI/L³, a rigidez à rotação em {other} cai de 4EI/L para 3EI/L e desaparece o termo de transmissão 2EI/L.",
  'dsm.step2.whyBothHinged': "Rotulada nas duas extremidades: a barra não transmite nenhum momento e sua rigidez à flexão desaparece de [k]; fica só EA/L, igual a uma barra de treliça. Uma carga no seu vão ainda chega aos nós, como as reações de uma viga simplesmente apoiada.",
  'dsm.step2.whyReleases3d': "Liberado nesta barra: {list}. Cada liberação condensa essa rotação: anulam-se sua linha e sua coluna, e nesse plano de flexão 12EI/L³ passa a 3EI/L³ (e 4EI/L a 3EI/L na outra extremidade). Liberar a torção elimina todo o bloco GJ/L.",
