  'loadPlan.derivation.dead': 'Carga permanente sobreposta: {total} kN/m².',
  'loadPlan.derivation.thermal': "Temperatura (T): ΔT = {dt} °C uniforme e {grad} °C de gradiente em {members} barras e {shells} placas.",
  'loadPlan.derivation.thermalSenses': "T nos dois sentidos (§2.3.4): o ΔT e o gradiente informados, e o seu inverso, como dois casos tomados um de cada vez em cada combinação com T.",
  'loadPlan.derivation.soil': "Empuxo do solo (H): p = K (γ z + q) com K = {k}, γ = {gamma} kN/m³ e q = {q} kN/m² abaixo do nível +{z} m; {total} kN sobre as placas verticais. K, γ e o nível são dados do projeto: o CIRSOC 101 não os fixa.",
  'loadPlan.derivation.fluid': "Fluido (F): γ = {gamma} kN/m³ até o nível +{z} m; pressão em {walls} nós de paredes e sobre {bottom} placas de fundo.",
  'loadPlan.note.noSoilWalls': "Não há placas verticais abaixo do nível +{z} m: o empuxo do solo não é aplicado.",
