  'pro.shellInfoMesh': 'Gerar malha subdivide a laje/parede em quads menores, criando MAIS nós de laje ao longo de cada borda.',
  'pro.shellInfoSlab': 'Caminho manual: subdivida primeiro as vigas de apoio e depois gere a malha da laje para que os seus nós de borda coincidam com os nós da viga (mesmos IDs). Nós coincidentes = conectados; as bordas sem coincidência não transferem carga entre si.',
