  'flex.scope': 'As oito abas da planilha são comparadas célula a célula, incluindo o bloco de armadura dupla, os seis pontos característicos e as séries de interação que elas plotam. Diferenças declaradas: as seções circulares saem ~0,6 % mais leves que na planilha; o corte da superfície na flexão oblíqua dá até 0,6 % mais no meio do quadrante, onde a planilha discretiza a zona comprimida; na aba circular, o momento da planilha no limite de carga axial é uma corda reta sobre um vão da sua própria grade e superestima a curva em 4,4 %, e aqui dá-se o ponto da curva; e, quando o aço não cabe numa camada, aqui empilha-se em várias e toma-se d no baricentro do grupo, o que exige mais aço que a planilha, que sempre supõe uma camada. Com normas posteriores a 2005 os resultados podem diferir e não são comparados com a planilha.',
