  'seismic.blocked.zone0': 'A Tabela 3.1 não define espectro para a zona sísmica 0. O art. 2.5.2 isenta construções de até 3 pavimentos ou 12 m, e as mais altas verificadas ao vento que cumpram c1, c2 e c3; o grupo Ao nunca é isento.',
  'seismic.blocked.siteSF': 'O sítio tipo SF exige avaliação específica do local (art. 2.3.2). A Tabela 3.1 não tem linha a ler.',
