  'seismic.derivation.taOnly': 'Ta = Cr·H^x = {cr}·{h}^{x} = {ta} s (expr. 6.8, Tabela 6.2).',
  'seismic.derivation.tComputed': 'Usa-se o período calculado T = {computed} s; fica abaixo do limite Cu·Ta = {cu}·{ta} = {limit} s (expr. 6.7).',
  'seismic.derivation.tCapped': 'O período calculado {computed} s supera o limite da expr. 6.7: adota-se Cu·Ta = {cu}·{ta} = {limit} s.',
  'seismic.derivation.cPlateau': 'T = {t} s ≤ T2 = {t2} s, portanto C = 2,5·Ca·γr/R = {sa}·{gammaR}/{r} = {c} (expr. 6.3).',
  'seismic.derivation.cSpectrum': 'T = {t} s > T2 = {t2} s, portanto C = Sa·γr/R = {sa}·{gammaR}/{r} = {c} (expr. 6.4).',
  'seismic.derivation.cFloorNearFault': 'Rege o mínimo da expr. 6.5 para as zonas 3 e 4: C = 0,8·as·Nv/R = 0,8·{as}·{nv}/{r} = {c}.',
