  'seismic.derivation.dist': 'Vo = {v0} kN distribuído em {levels} níveis segundo Wk·hk / ΣWi·hi, com ΣWi·hi = {sumWh} kN·m (expr. 6.11).',
  'seismic.derivation.distTopHeavy': 'T = {t} s supera 2·T2 = {t2} s: 90 % de Vo = {v0} kN distribui-se segundo Wk·hk (ΣWi·hi = {sumWh} kN·m) em {levels} níveis e os 10 % restantes aplicam-se inteiramente na última massa (exprs. 6.12 e 6.13).',
