  'solver.mechanismHingedNode': 'Mecanismo no nó {nodeId}: todas as {frames} barras têm rótula nesse nó e {doubleHinged} delas são birrotuladas (só esforço normal). O nó não tem rigidez à flexão nem rigidez transversal suficiente.',
