  'wind.other.hint.freeRoof': "p = qh G CN sobre as barras de cobertura: CNW na metade a barlavento e CNL na de sotavento com vento normal à cumeeira, e pela distância à borda com vento paralelo; casos A e B em cada direção. Normal à superfície, positiva para a face superior.",
  'wind.other.hint.latticeTower': "F = qz G Cf Af por nível de nós: Af = ε vezes a largura da face vezes a altura da faixa, Cf = 4,0ε² − 5,9ε + 4,0 (quadrada) ou 3,4ε² − 4,7ε + 3,4 (triangular); no mínimo 0,8 kN/m² vezes Af.",
