  'wind.other.hint.solidSign': "F = qh G Cf As sobre a face da placa (da altura livre para cima), Cf por B/s e s/h: caso A no centro e caso B a 0,2 B dele, para uma e outra borda. O caso C (B/s ≥ 2) não é gerado.",
