  'advHelp.despiece.text': 'Vista didática que separa cada barra de seus nós e desenha os esforços internos que ela transmite nas extremidades — normal N, cortante V e momento M — além das reações de apoio. As barras que compartilham um nó mostram pares de ação e reação iguais e opostos através da separação. Requer o modelo resolvido; usa os resultados atuais. Apenas visualização: não modifica o modelo nem recalcula.',
